import json
for f in ['03_interprocedural','04_alias_handling','05_lifecycle','06_library_summary','02_field_sensitivity']:
    d=json.load(open('benchmarks/%s.json'%f))
    print('='*70); print(f)
    for c in d['classes']:
        for m in c.get('methods',[]):
            b=m.get('body')
            if not b: continue
            print('  --',c['name'],'::',m['signature']['method_name'],'this=',b.get('this_local'),'params=',b.get('param_locals'))
            for s in b['statements']:
                bits=[str(s['stmt_id']),s['kind']]
                if s.get('lhs'): bits.append('lhs='+s['lhs'])
                if s.get('rhs'): bits.append('rhs='+str(s['rhs']))
                if s.get('rhs_vars'): bits.append('rhs_vars='+str(s['rhs_vars']))
                if s.get('field_ref'): bits.append('fld=%s.%s'%(s['field_ref']['base'],s['field_ref']['field_name']))
                if s.get('callee'): bits.append('callee=%s.%s'%(s['callee']['class_name'].split('.')[-1],s['callee']['method_name']))
                if s.get('receiver'): bits.append('recv='+s['receiver'])
                if s.get('args'): bits.append('args='+str(s['args']))
                if s.get('is_source'): bits.append('SOURCE')
                if s.get('is_sink'): bits.append('SINK')
                if s.get('condition'): bits.append('cond='+s['condition']+' T=%s F=%s'%(s.get('true_target'),s.get('false_target')))
                if s.get('metadata'): bits.append('meta='+json.dumps(s['metadata']))
                print('       ', ' | '.join(bits))
